using BARANG.Core.Application.Abstractions.Companies;using BARANG.Core.Application.Abstractions.Transactions;using BARANG.Core.Application.Auditing;using BARANG.Core.Application.Logistics;using BARANG.Core.Domain.Common;using BARANG.Core.Domain.Logistics;using BARANG.Core.Domain.Orders;using BARANG.Core.Domain.Organization;using BARANG.Core.Domain.Quality;using BARANG.Core.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;
namespace BARANG.Core.Infrastructure.Logistics;
#pragma warning disable CA1725,CA1305
public sealed class LogisticsAdministration(CoreDbContext db,ITransactionExecutor tx,ICompanyContext company,Application.Abstractions.Actors.ICurrentActor current,IAuditWriter audit,ICarrierService carrier,TimeProvider time):ILogisticsAdministration
{
 private Guid Company=>company.RequireCompanyId();private Guid Actor=>Guid.TryParse(current.Actor.UserId,out Guid id)?id:throw new InvalidOperationException("Actor required");private DateTimeOffset Now=>time.GetUtcNow();
 public Task<Result<PackageView>>CreatePackageAsync(CreatePackageCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Order?o=await db.Orders.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.OrderId,t);if(o is null||o.Status!=OrderStatus.Submitted)return Result.Failure<PackageView>(LogisticsErrors.NotReady);long seq=await Next("barang.package_number_seq",t);Result<Package>r=Package.Create(Company,o.Id,$"PKG-{Now.Year}-{seq:0000000000}",c.PackageTypeCode,c.WeightKg,c.LengthCm,c.WidthCm,c.HeightCm,Now);if(r.IsFailure)return Result.Failure<PackageView>(r.Error);db.Add(r.Value);Log("logistics.package.created",r.Value.Id);return Result.Success(View(r.Value,[]));},ct);
 public Task<Result<PackageView>>GetPackageAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Package?p=await db.Packages.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return p is null?Result.Failure<PackageView>(LogisticsErrors.NotFound):Result.Success(View(p,await Items(id,t)));},ct);
 public Task<Result<PackageView>>AddItemAsync(Guid id,AddPackageItemCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{await db.Database.ExecuteSqlInterpolatedAsync($"SELECT id FROM barang.order_items WHERE company_id={Company} AND id={c.OrderItemId} FOR UPDATE",t);Package?p=await db.Packages.SingleOrDefaultAsync(x=>x.Id==id,t);OrderItem?item=await db.OrderItems.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.OrderItemId&&x.IsActive,t);if(p is null||item is null)return Result.Failure<PackageView>(LogisticsErrors.NotFound);if(p.Status!=PackageStatus.Draft||item.OrderId!=p.OrderId||c.Quantity<=0)return Result.Failure<PackageView>(LogisticsErrors.InvalidTransition);if(await db.PackageItems.AnyAsync(x=>x.PackageId==id&&x.OrderItemId==item.Id,t))return Result.Failure<PackageView>(LogisticsErrors.Invalid);decimal allocated=await db.PackageItems.Where(x=>x.OrderItemId==item.Id).SumAsync(x=>(decimal?)x.Quantity,t)??0;if(allocated+c.Quantity>item.Quantity)return Result.Failure<PackageView>(LogisticsErrors.OverPackaged);Result<PackageItem>made=PackageItem.Create(Company,p.Id,p.OrderId,item.Id,c.Quantity,Now);if(made.IsFailure)return Result.Failure<PackageView>(made.Error);db.Add(made.Value);Log("logistics.package.item_added",p.Id);List<PackageItem>items=await db.PackageItems.Where(x=>x.PackageId==id).ToListAsync(t);items.Add(made.Value);return Result.Success(View(p,items));},ct);
 public Task<Result<PackageView>>CompletePackageAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Package?p=await db.Packages.SingleOrDefaultAsync(x=>x.Id==id,t);if(p is null)return Result.Failure<PackageView>(LogisticsErrors.NotFound);if(p.Status==PackageStatus.Completed)return Result.Success(View(p,await Items(id,t)));List<PackageItem>items=await db.PackageItems.Where(x=>x.PackageId==id).ToListAsync(t);if(items.Count==0)return Result.Failure<PackageView>(LogisticsErrors.NotReady);foreach(PackageItem pi in items)if(!await db.QCInspections.AnyAsync(x=>x.OrderItemId==pi.OrderItemId&&x.Outcome==QCOutcome.Approved,t))return Result.Failure<PackageView>(LogisticsErrors.NotReady);Result r=p.Complete(Actor,version,Now);if(r.IsFailure)return Result.Failure<PackageView>(r.Error);Log("logistics.package.completed",p.Id);return Result.Success(View(p,items));},ct);
 public Task<Result<HandoffView>>ReceiveHandoffAsync(Guid packageId,CreateHandoffCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Package?p=await db.Packages.SingleOrDefaultAsync(x=>x.Id==packageId,t);Warehouse?w=await db.Warehouses.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.WarehouseId&&x.IsActive&&x.Type==WarehouseType.Shipping,t);if(p is null||w is null)return Result.Failure<HandoffView>(LogisticsErrors.NotFound);ShippingHandoff?existing=await db.ShippingHandoffs.SingleOrDefaultAsync(x=>x.PackageId==packageId,t);if(existing is not null)return Result.Success(View(existing));Result state=p.Handoff(c.PackageVersion,Now);if(state.IsFailure)return Result.Failure<HandoffView>(state.Error);ShippingHandoff h=ShippingHandoff.Create(Company,p.Id,w.Id,Actor,Now);db.Add(h);Log("logistics.handoff.received",h.Id);return Result.Success(View(h));},ct);
 public Task<Result<HandoffView>>ReleaseHandoffAsync(Guid id,ReleaseHandoffCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ShippingHandoff?h=await db.ShippingHandoffs.SingleOrDefaultAsync(x=>x.Id==id,t);if(h is null)return Result.Failure<HandoffView>(LogisticsErrors.NotFound);Package p=await db.Packages.SingleAsync(x=>x.Id==h.PackageId,t);Result r=h.Release(Actor,c.HandoffVersion,Now);if(r.IsFailure)return Result.Failure<HandoffView>(r.Error);Result pr=p.Release(c.PackageVersion,Now);if(pr.IsFailure)return Result.Failure<HandoffView>(pr.Error);Log("logistics.handoff.released",h.Id);return Result.Success(View(h));},ct);
 public Task<Result<ShipmentView>>CreateShipmentAsync(CreateShipmentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(c.PackageIds.Count==0||c.PackageIds.Distinct().Count()!=c.PackageIds.Count)return Result.Failure<ShipmentView>(LogisticsErrors.Invalid);List<ShipmentPackage>assigned=await db.ShipmentPackages.Where(x=>c.PackageIds.Contains(x.PackageId)).ToListAsync(t);if(assigned.Count>0){Guid sid=assigned[0].ShipmentId;if(assigned.Count==c.PackageIds.Count&&assigned.All(x=>x.ShipmentId==sid))return Result.Success(await ShipmentView(await db.Shipments.SingleAsync(x=>x.Id==sid,t),t));return Result.Failure<ShipmentView>(LogisticsErrors.AlreadyAssigned);}List<Package>packages=await db.Packages.Where(x=>c.PackageIds.Contains(x.Id)).ToListAsync(t);if(packages.Count!=c.PackageIds.Count||packages.Any(x=>x.OrderId!=c.OrderId||x.Status is not(PackageStatus.Completed or PackageStatus.AtShippingWarehouse)))return Result.Failure<ShipmentView>(LogisticsErrors.NotReady);long seq=await Next("barang.shipment_number_seq",t);Result<Shipment>made=Shipment.Create(Company,c.OrderId,$"SHP-{Now.Year}-{seq:0000000000}",c.CarrierCode,c.ShippingMethodCode,c.ExpectedDeliveryDate,Now);if(made.IsFailure)return Result.Failure<ShipmentView>(made.Error);db.Add(made.Value);foreach(Package p in packages){ShippingHandoff?h=await db.ShippingHandoffs.SingleOrDefaultAsync(x=>x.PackageId==p.Id,t);if(h is not null&&h.Status==ShippingHandoffStatus.Received){Result hr=h.Release(Actor,h.Version,Now);if(hr.IsFailure)return Result.Failure<ShipmentView>(hr.Error);Log("logistics.handoff.released",h.Id);}Result r=p.Release(p.Version,Now);if(r.IsFailure)return Result.Failure<ShipmentView>(r.Error);db.Add(ShipmentPackage.Create(Company,made.Value.Id,p.Id,Now));}Status(made.Value,null,null);Log("logistics.shipment.created",made.Value.Id);return Result.Success(await ShipmentView(made.Value,t,c.PackageIds));},ct);
 public Task<Result<ShipmentView>>GetShipmentAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Shipment?s=await db.Shipments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,t);return s is null?Result.Failure<ShipmentView>(LogisticsErrors.NotFound):Result.Success(await ShipmentView(s,t));},ct);
 public Task<Result<ShipmentView>>RegisterTrackingAsync(Guid id,RegisterTrackingCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Shipment?s=await db.Shipments.SingleOrDefaultAsync(x=>x.Id==id,t);if(s is null)return Result.Failure<ShipmentView>(LogisticsErrors.NotFound);Result<string>normalized=carrier.NormalizeTracking(s.CarrierCode,c.TrackingCode);if(normalized.IsFailure)return Result.Failure<ShipmentView>(normalized.Error);long before=s.Version;Result r=s.RegisterTracking(normalized.Value,c.Version,Now);if(r.IsFailure)return Result.Failure<ShipmentView>(r.Error);if(s.Version!=before)Log("logistics.tracking.registered",s.Id);return Result.Success(await ShipmentView(s,t));},ct);
 public Task<Result<ShipmentView>>MarkShippedAsync(Guid id,long version,CancellationToken ct)=>Change(id,version,(s,v)=>s.Ship(v,Now),null,null,"logistics.shipment.shipped",ct);public Task<Result<ShipmentView>>MarkInTransitAsync(Guid id,long version,CancellationToken ct)=>Change(id,version,(s,v)=>s.InTransit(v,Now),null,null,"logistics.shipment.in_transit",ct);public Task<Result<ShipmentView>>ConfirmDeliveryAsync(Guid id,long version,CancellationToken ct)=>Change(id,version,(s,v)=>s.Deliver(v,Now),null,null,"logistics.delivery.confirmed",ct);public Task<Result<ShipmentView>>FailDeliveryAsync(Guid id,LogisticsReasonCommand c,CancellationToken ct)=>Change(id,c.Version,(s,v)=>s.Fail(c.ReasonCode,c.ReasonText,v,Now),c.ReasonCode,c.ReasonText,"logistics.delivery.failed",ct);
 public Task<Result<ShipmentView>>ReturnAsync(Guid id,ReturnShipmentCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Warehouses.AnyAsync(x=>x.Id==c.WarehouseId&&x.IsActive&&x.Type==WarehouseType.Returns,t))return Result.Failure<ShipmentView>(LogisticsErrors.NotFound);Shipment?s=await db.Shipments.SingleOrDefaultAsync(x=>x.Id==id,t);if(s is null)return Result.Failure<ShipmentView>(LogisticsErrors.NotFound);long before=s.Version;Result r=s.Return(c.WarehouseId,c.ReasonCode,c.ReasonText,c.Version,Now);if(r.IsFailure)return Result.Failure<ShipmentView>(r.Error);if(s.Version!=before){Status(s,c.ReasonCode,c.ReasonText);Log("logistics.shipment.returned",s.Id);}return Result.Success(await ShipmentView(s,t));},ct);
 private Task<Result<ShipmentView>>Change(Guid id,long version,Func<Shipment,long,Result>f,string?code,string?reason,string action,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Shipment?s=await db.Shipments.SingleOrDefaultAsync(x=>x.Id==id,t);if(s is null)return Result.Failure<ShipmentView>(LogisticsErrors.NotFound);long before=s.Version;Result r=f(s,version);if(r.IsFailure)return Result.Failure<ShipmentView>(r.Error);if(s.Version!=before){Status(s,code,reason);Log(action,s.Id);}return Result.Success(await ShipmentView(s,t));},ct);
 public Task<Result<IReadOnlyList<ShipmentHistoryView>>>HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(!await db.Shipments.AnyAsync(x=>x.Id==id,t))return Result.Failure<IReadOnlyList<ShipmentHistoryView>>(LogisticsErrors.NotFound);return Result.Success<IReadOnlyList<ShipmentHistoryView>>((await db.ShipmentStatusHistory.AsNoTracking().Where(x=>x.ShipmentId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new ShipmentHistoryView(x.Id,x.Status,x.OccurredAtUtc,x.ActorUserId,x.SourceCode,x.ReasonCode,x.ReasonText)).ToArray());},ct);
 private async Task<long>Next(string sequence,CancellationToken t){await using var c=db.Database.GetDbConnection().CreateCommand();c.CommandText=$"SELECT nextval('{sequence}')";c.Transaction=db.Database.CurrentTransaction!.GetDbTransaction();return Convert.ToInt64(await c.ExecuteScalarAsync(t),System.Globalization.CultureInfo.InvariantCulture);}private Task<List<PackageItem>>Items(Guid p,CancellationToken t)=>db.PackageItems.AsNoTracking().Where(x=>x.PackageId==p).OrderBy(x=>x.CreatedAtUtc).ToListAsync(t);private void Status(Shipment s,string?code,string?reason)=>db.ShipmentStatusHistory.Add(ShipmentStatusHistory.Create(Company,s.Id,s.Status,Actor,Now,"CORE",code,reason));private void Log(string action,Guid id)=>audit.Write(new(action,"logistics",id.ToString(),ChangeKind:AuditChangeKind.Modified));private static PackageView View(Package p,IReadOnlyList<PackageItem>i)=>new(p.Id,p.OrderId,p.PackageNumber,p.PackageTypeCode,p.WeightKg,p.LengthCm,p.WidthCm,p.HeightCm,p.Status,p.CompletedAtUtc,p.Version,i.Select(x=>new PackageItemView(x.Id,x.OrderItemId,x.Quantity)).ToArray());private static HandoffView View(ShippingHandoff h)=>new(h.Id,h.PackageId,h.WarehouseId,h.Status,h.ReceivedAtUtc,h.ReleasedAtUtc,h.Version);private async Task<ShipmentView>ShipmentView(Shipment s,CancellationToken t,IReadOnlyList<Guid>?ids=null)=>new(s.Id,s.OrderId,s.ShipmentNumber,s.CarrierCode,s.ShippingMethodCode,s.TrackingCode,s.ShipmentDateUtc,s.ExpectedDeliveryDate,s.DeliveredAtUtc,s.Status,s.LastReasonCode,s.LastReasonText,s.Version,ids??await db.ShipmentPackages.AsNoTracking().Where(x=>x.ShipmentId==s.Id).Select(x=>x.PackageId).ToListAsync(t));
}
#pragma warning restore CA1725,CA1305
